This is more generic and elegant fix (not depends on forced only setting):

```diff
diff --git a/xbmc/cores/VideoPlayer/VideoPlayer.cpp b/xbmc/cores/VideoPlayer/VideoPlayer.cpp
index c4ab6dcb94..6c110c7885 100644
--- a/xbmc/cores/VideoPlayer/VideoPlayer.cpp
+++ b/xbmc/cores/VideoPlayer/VideoPlayer.cpp
@@ -253,6 +253,19 @@ public:
     return !filter(ss);
   }
 
+  bool IsNeedOpen(const SelectionStream& ss) const
+  {
+    if (relevant(ss))
+      return true;
+
+   // Even if the subtitle is "not relevant", it's necessary open it to read
+   // possible forced subtitles, only if the language is the same as the audio
+    if (g_LangCodeExpander.CompareISO639Codes(ss.language, audiolang))
+      return true;
+
+    return false;
+  }
+
   bool operator()(const SelectionStream& lh, const SelectionStream& rh) const
   {
     PREDICATE_RETURN(relevant(lh)
@@ -964,6 +977,8 @@ void CVideoPlayer::OpenDefaultStreams(bool reset)
   if (m_CurrentSubtitle.source == STREAM_SOURCE_VIDEOMUX)
     CloseStream(m_CurrentSubtitle, false);
 
+  SelectionStream ss;
+
   for (const auto &stream : m_SelectionStreams.Get(STREAM_SUBTITLE, psp))
   {
     if (OpenStream(m_CurrentSubtitle, stream.demuxerId, stream.id, stream.source))
@@ -973,12 +988,19 @@ void CVideoPlayer::OpenDefaultStreams(bool reset)
         visible = false;
       else if(stream.flags & StreamFlags::FLAG_FORCED)
         visible = true;
+      ss = stream; // store current selected stream
       break;
     }
   }
   if(!valid)
     CloseStream(m_CurrentSubtitle, false);
 
+  if (valid && !visible && !psp.IsNeedOpen(ss))
+  {
+    CloseStream(m_CurrentSubtitle, false);
+    valid = false;
+  }
+
   // only set subtitle visibility if state not stored by dvd navigator, because navigator will restore it (if visible)
   if (!std::dynamic_pointer_cast<CDVDInputStreamNavigator>(m_pInputStream) ||
